CREATE OR REPLACE FUNCTION public.estim_registration_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT(EXISTS(SELECT 1 FROM public.company_invitations WHERE email=lower(NEW.email) AND expires_at>now() AND accepted_at IS NULL AND revoked_at IS NULL) OR EXISTS(SELECT 1 FROM public.platform_admin_invitations WHERE email=lower(NEW.email) AND expires_at>now() AND accepted_at IS NULL)) THEN RAISE EXCEPTION 'Registration requires an invitation'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.estim_new_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.estim_confirm_platform_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.email_confirmed_at IS NOT NULL AND NEW.invited_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.platform_admin_invitations WHERE email=lower(NEW.email) AND expires_at>now() AND accepted_at IS NULL) THEN INSERT INTO public.platform_admins(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; UPDATE public.platform_admin_invitations SET accepted_at=now() WHERE email=lower(NEW.email); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.estim_confirm_platform_admin() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER estim_platform_admin_verified AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.estim_confirm_platform_admin();